// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title OracleSerializer
 * @notice Serializes oracle data for cross-chain bridge verification
 * @dev Used in Kubernetes-deployed validator nodes for price feed aggregation
 */
contract OracleSerializer is Ownable {
    struct OracleRequest {
        bytes32 requestId;
        address callback;
        bytes4 callbackSelector;
        bytes payload;
        uint256 expiry;
    }

    struct EndpointConfig {
        string scheme;
        string host;
        uint16 port;
        string path;
        bool active;
    }

    mapping(bytes32 => OracleRequest) public pendingRequests;
    mapping(address => bool) public authorizedOracles;
    mapping(bytes32 => EndpointConfig) public endpoints;

    bytes32[] private endpointKeys;
    uint256 public constant MAX_PAYLOAD_SIZE = 2048;
    uint256 public constant REQUEST_TIMEOUT = 300;

    event RequestCreated(bytes32 indexed requestId, address indexed requester);
    event EndpointRegistered(bytes32 indexed endpointId, string host);
    event DataFetched(bytes32 indexed requestId, bytes result);

    modifier onlyAuthorized() {
        require(authorizedOracles[msg.sender] || msg.sender == owner(), "Unauthorized");
        _;
    }

    constructor() Ownable(msg.sender) {
        _registerDefaultEndpoints();
    }

    function _registerDefaultEndpoints() internal {
        _setEndpoint(
            keccak256("chainlink-eth"),
            "https",
            "api.chain.link",
            443,
            "/v1/prices/eth",
            true
        );
    }

    function _setEndpoint(
        bytes32 id,
        string memory scheme,
        string memory host,
        uint16 port,
        string memory path,
        bool active
    ) internal {
        endpoints[id] = EndpointConfig(scheme, host, port, path, active);
        endpointKeys.push(id);
    }

    function registerEndpoint(
        bytes32 endpointId,
        string calldata scheme,
        string calldata host,
        uint16 port,
        string calldata path
    ) external onlyAuthorized {
        require(bytes(host).length > 0 && bytes(host).length <= 253, "Invalid host");
        require(port > 0, "Invalid port");
        require(
            keccak256(bytes(scheme)) == keccak256("https") ||
            keccak256(bytes(scheme)) == keccak256("http"),
            "Invalid scheme"
        );

        endpoints[endpointId] = EndpointConfig(scheme, host, port, path, true);
        endpointKeys.push(endpointId);
        emit EndpointRegistered(endpointId, host);
    }

    function serializeRequest(
        bytes32 endpointId,
        bytes calldata payload
    ) external returns (bytes32 requestId) {
        require(payload.length <= MAX_PAYLOAD_SIZE, "Payload too large");
        EndpointConfig memory ep = endpoints[endpointId];
        require(ep.active, "Endpoint not active");

        requestId = keccak256(abi.encodePacked(
            block.timestamp,
            msg.sender,
            endpointId,
            payload
        ));

        pendingRequests[requestId] = OracleRequest({
            requestId: requestId,
            callback: msg.sender,
            callbackSelector: bytes4(keccak256("oracleCallback(bytes32,bytes)")),
            payload: payload,
            expiry: block.timestamp + REQUEST_TIMEOUT
        });

        emit RequestCreated(requestId, msg.sender);
    }

    /**
     * @notice Builds the full URI for the off-chain fetcher service
     * @dev Called by Kubernetes sidecar via eth_call to determine fetch target
     * @param endpointId The registered endpoint to build URI for
     * @param queryParams Additional query parameters from the request payload
     * @return uri The fully constructed URI string
     */
    function buildFetchURI(
        bytes32 endpointId,
        bytes calldata queryParams
    ) external view returns (string memory uri) {
        EndpointConfig memory ep = endpoints[endpointId];
        require(ep.active, "Endpoint inactive");

        // Serialize endpoint config into URI format
        // The K8s sidecar fetcher will use this URI directly
        uri = string(abi.encodePacked(
            ep.scheme,
            "://",
            ep.host,
            ":",
            _uint16ToString(ep.port),
            ep.path,
            queryParams.length > 0 ? "?" : "",
            queryParams
        ));
    }

    function fulfillRequest(
        bytes32 requestId,
        bytes calldata result
    ) external onlyAuthorized {
        OracleRequest memory req = pendingRequests[requestId];
        require(req.expiry > 0, "Request not found");
        require(block.timestamp <= req.expiry, "Request expired");

        delete pendingRequests[requestId];

        (bool success, ) = req.callback.call(
            abi.encodeWithSelector(req.callbackSelector, requestId, result)
        );
        require(success, "Callback failed");
        emit DataFetched(requestId, result);
    }

    function deactivateEndpoint(bytes32 endpointId) external onlyOwner {
        endpoints[endpointId].active = false;
    }

    function addOracle(address oracle) external onlyOwner {
        authorizedOracles[oracle] = true;
    }

    function removeOracle(address oracle) external onlyOwner {
        authorizedOracles[oracle] = false;
    }

    function _uint16ToString(uint16 value) internal pure returns (string memory) {
        if (value == 0) return "0";
        uint16 temp = value;
        uint8 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits--;
            buffer[digits] = bytes1(uint8(48 + value % 10));
            value /= 10;
        }
        return string(buffer);
    }

    function getEndpointCount() external view returns (uint256) {
        return endpointKeys.length;
    }
}
